"""Hosted override for the pinned image; no request/message/exception contents."""
import logging
import logging.config
import re
import socket
from celery.signals import setup_logging

from pretix.settings import *  # noqa: F403
from pretix.helpers.apps import PretixHelpersConfig

STORAGES['staticfiles']['BACKEND'] = 'django.contrib.staticfiles.storage.ManifestStaticFilesStorage'

# Keep the pinned image's private-network protection active. Its urllib3 hook
# checks the resolved socket address at connect time; allow only the unpublished
# proxy webhook listener, whose sole route authenticates booking notifications.
ALLOW_HTTP_TO_PRIVATE_NETWORKS = False


class HostedPretixHelpersConfig(PretixHelpersConfig):
    def ready(self):
        # Import after Django populates apps: importing Pretix's monkeypatching
        # module while settings load imports models before the app registry exists.
        from pretix.helpers import monkeypatching
        upstream_should_block_access = monkeypatching.should_block_access

        def booking_webhook_private_access(address):
            host, port = address[:2]
            if port == 8081:
                try:
                    proxy_ips = {info[4][0] for info in socket.getaddrinfo('proxy', 8081,
                                 type=socket.SOCK_STREAM)}
                except OSError:
                    proxy_ips = set()
                if host in proxy_ips:
                    return False, ''
            return upstream_should_block_access(address)

        monkeypatching.should_block_access = booking_webhook_private_access
        super().ready()
        configure_ttd_presentation()


INSTALLED_APPS[INSTALLED_APPS.index('pretix.helpers')] = 'production_settings.HostedPretixHelpersConfig'


class PrivateFormatter(logging.Formatter):
    def format(self, record):
        name = re.sub(r'[^a-zA-Z0-9_.-]', '_', record.name)[:128]
        kind = record.exc_info[0].__name__ if record.exc_info else ''
        return f'{record.levelname} {name}' + (f' [{kind}]' if kind else '')


LOGGING = {
    'version': 1, 'disable_existing_loggers': False,
    'formatters': {'private': {'()': PrivateFormatter}},
    'handlers': {'console': {'class': 'logging.StreamHandler', 'formatter': 'private'}},
    'root': {'handlers': ['console'], 'level': 'WARNING'},
    'loggers': {name: {'handlers': ['console'], 'level': 'WARNING', 'propagate': False}
                for name in ('pretix', 'django', 'django.request', 'django.server',
                             'django.security', 'celery', 'celery.task', 'celery.redirected',
                             'multiprocessing')},
}


@setup_logging.connect(weak=False)
def configure_celery_logging(**kwargs):
    # Celery otherwise installs formatters that include task arguments/tracebacks.
    logging.config.dictConfig(LOGGING)


# Supplied TTD artwork, resized without changing its proportions. Inline assets
# work inside private checkout and do not require a public media exception.
TTD_LOGOS = {'green': '', 'purple': ''}


def ttd_theme(event):
    if not event or event.organizer.slug != 'dd-studio':
        return None
    return ('green', '#116E3A', '#DAF2E5') if event.slug == 'studio' else ('purple', '#7349CD', '#EFE9FB')


def ttd_checkout_style(event):
    theme = ttd_theme(event)
    if not theme:
        return ''
    _, ink, background = theme
    return '<style>' + """
body { color: INK; background: BACKGROUND; }
.ttd-checkout-brand { max-width: 1140px; margin: 24px auto 8px; padding: 0 20px; }
.ttd-checkout-brand img { display:block; width:180px; max-width:100%; height:auto; }
.main-box { border-radius:0; padding-top:24px; }
a { color:INK; }
.btn-primary { background:INK; border-color:INK; border-radius:0; }
.btn-primary:hover,.btn-primary:focus { background:INK; filter:brightness(.85); border-color:INK; }
.panel,.form-control,.btn { border-radius:0; }
.form-group { margin-bottom:20px; }
.form-control { min-height:44px; }
.checkout-button-row { margin-top:24px; display:flex; flex-wrap:wrap; gap:12px; align-items:center; }
.checkout-button-row .btn { min-height:44px; white-space:normal; }
.stripe-card-holder { width:100%; }
.stripe-payment-request-button-container { margin-top:16px; width:100%; }
input:focus,select:focus,textarea:focus { border-color:INK; outline:2px solid INK; outline-offset:2px; }
@media(max-width:600px) {
 .main-box { width:auto; margin:12px; padding:20px 16px; }
 .ttd-checkout-brand { margin-top:20px; }
 .form-control { font-size:16px; }
 .checkout-button-row .btn { flex:1 1 auto; }
 table { max-width:100%; }
 .cart-row h3,.panel-heading { overflow-wrap:anywhere; }
}
""".replace('INK', ink).replace('BACKGROUND', background) + '</style>'


def configure_ttd_presentation():
    from django.utils.safestring import mark_safe
    from pretix.presale.signals import global_html_head, global_html_page_header

    def head(sender, request, **kwargs):
        return mark_safe(ttd_checkout_style(getattr(request, 'event', None)))

    def header(sender, request, **kwargs):
        theme = ttd_theme(getattr(request, 'event', None))
        if not theme:
            return ''
        return mark_safe('<div class="ttd-checkout-brand"><img alt="TTD Studio" width="240" height="105" src="data:image/png;base64,' + TTD_LOGOS[theme[0]] + '" /></div>')

    global_html_head.connect(head, weak=False, dispatch_uid='ttd_checkout_style')
    global_html_page_header.connect(header, weak=False, dispatch_uid='ttd_checkout_logo')
